//! Test-only helpers for the shared vectors in `tests/fixtures/*.json`
//! (generated by `scripts/dev/gen-fixtures.ts`). A tiny JSON reader keeps
//! float-core free of dependencies, dev-dependencies included.

#![allow(dead_code)]

use float_core::CoreError;

/// A parsed JSON value. Numbers keep their source text so big integers are exact.
#[derive(Debug, Clone, PartialEq)]
pub enum Json {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    /// Field of an object; panics with the key name if missing.
    pub fn get(&self, key: &str) -> &Json {
        match self {
            Json::Obj(fields) => {
                fields.iter().find(|(k, _)| k == key).map(|(_, v)| v).unwrap_or_else(|| panic!("missing key {key:?} in {self:?}"))
            }
            _ => panic!("not an object: {self:?}"),
        }
    }

    pub fn opt(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(fields) => fields.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }

    pub fn arr(&self) -> &[Json] {
        match self {
            Json::Arr(v) => v,
            _ => panic!("not an array: {self:?}"),
        }
    }

    pub fn str(&self) -> &str {
        match self {
            Json::Str(s) => s,
            _ => panic!("not a string: {self:?}"),
        }
    }

    pub fn bool(&self) -> bool {
        match self {
            Json::Bool(b) => *b,
            _ => panic!("not a bool: {self:?}"),
        }
    }

    fn text(&self) -> &str {
        match self {
            Json::Num(s) | Json::Str(s) => s,
            _ => panic!("not a number: {self:?}"),
        }
    }

    pub fn u128(&self) -> u128 {
        self.text().parse().unwrap_or_else(|_| panic!("not a u128: {self:?}"))
    }

    pub fn u64(&self) -> u64 {
        self.text().parse().unwrap_or_else(|_| panic!("not a u64: {self:?}"))
    }

    pub fn i64(&self) -> i64 {
        self.text().parse().unwrap_or_else(|_| panic!("not an i64: {self:?}"))
    }

    pub fn u32(&self) -> u32 {
        self.text().parse().unwrap_or_else(|_| panic!("not a u32: {self:?}"))
    }

    pub fn u16(&self) -> u16 {
        self.text().parse().unwrap_or_else(|_| panic!("not a u16: {self:?}"))
    }

    pub fn u8(&self) -> u8 {
        self.text().parse().unwrap_or_else(|_| panic!("not a u8: {self:?}"))
    }

    /// A one-byte address shorthand `b` → `[b; 32]`.
    pub fn addr(&self) -> [u8; 32] {
        [self.u8(); 32]
    }
}

/// Parses a JSON document (objects, arrays, strings without unicode escapes, numbers, literals).
pub fn parse(src: &str) -> Json {
    let mut p = Parser { s: src.as_bytes(), i: 0 };
    let v = p.value();
    p.ws();
    assert_eq!(p.i, p.s.len(), "trailing characters in JSON");
    v
}

struct Parser<'a> {
    s: &'a [u8],
    i: usize,
}

impl Parser<'_> {
    fn ws(&mut self) {
        while self.i < self.s.len() && self.s[self.i].is_ascii_whitespace() {
            self.i += 1;
        }
    }

    fn eat(&mut self, c: u8) {
        self.ws();
        assert_eq!(self.s[self.i], c, "expected {:?} at byte {}", c as char, self.i);
        self.i += 1;
    }

    fn value(&mut self) -> Json {
        self.ws();
        match self.s[self.i] {
            b'{' => {
                self.i += 1;
                let mut fields = Vec::new();
                self.ws();
                if self.s[self.i] == b'}' {
                    self.i += 1;
                    return Json::Obj(fields);
                }
                loop {
                    self.ws();
                    let k = self.string();
                    self.eat(b':');
                    fields.push((k, self.value()));
                    self.ws();
                    let c = self.s[self.i];
                    self.i += 1;
                    if c == b'}' {
                        return Json::Obj(fields);
                    }
                    assert_eq!(c, b',', "expected , or }} at byte {}", self.i - 1);
                }
            }
            b'[' => {
                self.i += 1;
                let mut items = Vec::new();
                self.ws();
                if self.s[self.i] == b']' {
                    self.i += 1;
                    return Json::Arr(items);
                }
                loop {
                    items.push(self.value());
                    self.ws();
                    let c = self.s[self.i];
                    self.i += 1;
                    if c == b']' {
                        return Json::Arr(items);
                    }
                    assert_eq!(c, b',', "expected , or ] at byte {}", self.i - 1);
                }
            }
            b'"' => Json::Str(self.string()),
            b't' => self.literal("true", Json::Bool(true)),
            b'f' => self.literal("false", Json::Bool(false)),
            b'n' => self.literal("null", Json::Null),
            _ => {
                let start = self.i;
                while self.i < self.s.len() && matches!(self.s[self.i], b'-' | b'+' | b'.' | b'e' | b'E' | b'0'..=b'9') {
                    self.i += 1;
                }
                Json::Num(String::from_utf8(self.s[start..self.i].to_vec()).unwrap())
            }
        }
    }

    fn literal(&mut self, word: &str, v: Json) -> Json {
        assert!(self.s[self.i..].starts_with(word.as_bytes()), "bad literal at byte {}", self.i);
        self.i += word.len();
        v
    }

    fn string(&mut self) -> String {
        assert_eq!(self.s[self.i], b'"');
        self.i += 1;
        let mut out = Vec::new();
        while self.s[self.i] != b'"' {
            if self.s[self.i] == b'\\' {
                self.i += 1;
                out.push(match self.s[self.i] {
                    b'n' => b'\n',
                    b't' => b'\t',
                    c @ (b'"' | b'\\' | b'/') => c,
                    c => panic!("unsupported escape \\{}", c as char),
                });
            } else {
                out.push(self.s[self.i]);
            }
            self.i += 1;
        }
        self.i += 1;
        String::from_utf8(out).unwrap()
    }
}

/// Name of a `CoreError` variant, as the TypeScript SDK spells error codes.
pub fn err_name(e: CoreError) -> String {
    format!("{e:?}")
}

/// Checks a `Result` against an expected `{ "ok": … }` / `{ "err": "Name" }`.
/// `check_ok` compares the success value with the `ok` payload.
pub fn check<T: core::fmt::Debug>(case: &str, got: Result<T, CoreError>, expected: &Json, check_ok: impl FnOnce(&T, &Json)) {
    match (got, expected.opt("ok"), expected.opt("err")) {
        (Ok(v), Some(ok), None) => check_ok(&v, ok),
        (Err(e), None, Some(err)) => assert_eq!(err_name(e), err.str(), "{case}: wrong error"),
        (got, _, _) => panic!("{case}: got {got:?}, expected {expected:?}"),
    }
}
